-- 0036_roam_paths (v0.54): roaming enemies walk round things instead of through them.
--
-- Thugs, rats, guard dogs, giant rats and bikers stroll from spot to spot on a fixed schedule (game.thug_at,
-- game.rat_at, game.roam_at). Between two spots they walked a straight line: through the Yard's couch and barrel,
-- crates, the junk. Now, when the straight line isn't clear, they walk round it, over the floor tiles of their own
-- place (the same moves a player can make). The schedule stays exactly the same: which spot, and when. Only the
-- position during a walk changes.
--
-- The detours are worked out once in the game's code (src/game/roamPaths.ts) and stored here, one row per (from, to)
-- pair that needs one (game.roam_paths, printed by scripts/roam-paths-sql.ts), so the server only looks a row up: no
-- pathfinding in the database. game.walk_point walks a detour the same way the game does.
--
-- Because the position functions now read a table, they go from IMMUTABLE to STABLE (same results, only Postgres's
-- bookkeeping changes). game.enemy_at too (it calls them).
--
-- Nothing is deleted: a new table, a new function, three functions replaced with the same signatures.
-- One transaction: to try it first, replace "commit;" at the end with "rollback;". The check should say "ok".

begin;

-- ---------- 1. The detours (only the server's functions read them) ----------
create table if not exists game.roam_paths (
  fx smallint not null, fy smallint not null, tx smallint not null, ty smallint not null,
  xs smallint[] not null, ys smallint[] not null,
  primary key (fx, fy, tx, ty)
);
alter table game.roam_paths enable row level security;
revoke all on game.roam_paths from public, anon, authenticated;
truncate game.roam_paths;
insert into game.roam_paths (fx, fy, tx, ty, xs, ys) values
